// === Tab: ProcessingPlayground ===
/*
.-. .-. .-. .-. .-. .-. .-. .-. . . .-.   .-. .   .-. . . .-. .-. .-. . . . . .-. 
|-' |(  | | |   |-  `-. `-.  |  |\| |..   |-' |   |-|  |  |.. |(  | | | | |\| |  )
'   ' ' `-' `-' `-' `-' `-' `-' ' ` `-'   '   `-' ` '  `  `-' ' ' `-' `-' ' ` `-'  by jfavlam

                                        let here >>> github.com/jfavlam/ProcessingPlayground
*/

let polygons;
let colorPalette = [
    "#dd7040", "#55bf99", "#5e55bc"
];
let randomColor;

let bground = 6;
let mdground = 10;
let frground = 16;
let bgsize = 80;
let mdsize = 60;
let frsize = 40;
let total = bground+mdground+frground;

function setup() {
    createCanvas(600, 600);
    smooth();
    rectMode(RADIUS);
    strokeCap(ROUND);
    strokeJoin(ROUND);
    randomColor = int(random(colorPalette.length));
    polygons = new Array(total);

    for (i = 0; i < polygons.length; i++) {
        if (i < bground) { 
            polygons[i] = new Polygon(random(0, width), random(0, height), bgsize, int(random(3, 6)), 0.5);
        } else if (i < mdground+bground) {
            polygons[i] = new Polygon(random(0, width), random(0, height), mdsize, int(random(3, 6)), 0.3);
        } else if (i >= mdground) {
            polygons[i] = new Polygon(random(0, width), random(0, height), frsize, int(random(3, 6)), 0.1);
        }
    }

    let keyBall = polygons[int(random(polygons.length))];
    keyBall.isKey = true;
}

function draw() {
    background(colorPalette[randomColor]);

    for (i = 0; i < polygons.length; i++) {
        polygons[i].move();
        polygons[i].display();
        polygons[i].plop.display();
        polygons[i].plop.update();
    }
}
class Plop {

    verticesIn, verticesOut;
    angle;
    position;
    sxIn = 0;
    syIn = 0;
    sxOut = 0;
    syOut = 0;
    npoints;
    radius, endRadius;
    incrOut, incrIn;
    lineWeight = 20;
    rot;
    alpha = 255;

    constructor(_x, _y, _radius, _npoints, _duration) {
        npoints = _npoints;
        radius = _radius;
        endRadius = _radius;
        angle = TWO_PI / npoints;
        verticesIn = new Array(npoints);
        verticesOut = new Array(npoints);
        incrIn =radius;
        incrOut = radius;
        position = new PVector(_x, _y);

        for (i = 0; i < npoints; i++) {
            sxIn = position.x + cos(i*angle) * radius;
            syIn = position.y + sin(i*angle) * radius;
            sxOut = position.x + cos(i*angle) * (incrOut);
            syOut = position.y + sin(i*angle) * (incrOut);
            verticesIn[i] = new PVector(sxIn, syIn);
            verticesOut[i] = new PVector(sxOut, syOut);
        }

        rot = random(0, 60);
    }

    function display() {
        pushStyle();
        stroke(255, alpha);
        strokeWeight(lineWeight);
        noFill();
        pushMatrix();

        for (i = 0; i < verticesIn.length; i++) {
            line(verticesIn[i].x, verticesIn[i].y, verticesOut[i].x, verticesOut[i].y);
        }

        popMatrix();
        popStyle();
    }

    function update() {
        rot += 0;

        if (incrOut < radius+40)
            incrOut += 10;

        if (incrOut == radius+40 && incrIn < radius+40) {
            incrIn += 10;
            alpha-=10;
        }

        if (incrIn == radius+40 && lineWeight > 0)
            lineWeight-=2;

        for (i = 0; i < npoints; i++) {
            sxIn = position.x + cos(i*angle+rot) * (radius + incrIn);
            syIn = position.y + sin(i*angle+rot) * (radius + incrIn);
            sxOut = position.x + cos(i*angle+rot) * (radius +incrOut);
            syOut = position.y + sin(i*angle+rot) * (radius +incrOut);
            verticesIn[i] = new PVector(sxIn, syIn);
            verticesOut[i] = new PVector(sxOut, syOut);
        }
    }
}
class Polygon {

    angle;
    vertices;
    position;
    sx = 0;
    sy = 0;
    npoints;
    radius, endRadius, rad;
    isActive;
    frame;
    factor;
    isKey;
    test;
    rot;
    plop;

    constructor(x, y, _radius, _npoints, _factor) {
        npoints = _npoints;
        radius = 0;
        rad = _radius;
        endRadius = _radius;
        angle = TWO_PI / npoints;
        vertices = new Array(npoints);
        position = new PVector(x, y);

        for (i = 0; i < npoints; i++) {
            sx = x + cos(i*angle) * radius;
            sy = y + sin(i*angle) * radius; 
            vertices[i] = new PVector(sx, sy);
        }

        factor = _factor * random(1, 2);
        plop = new Plop(0, 0, 60, npoints, 10);
    }

    function display() {
        frame+=0.1;

        rot+= factor/100;
        plop.position = this.position;
        if (radius < endRadius)
            radius = radius + (endRadius - radius) * random(0.01, 0.09);
        else
            radius = endRadius;

        for (i = 0; i < npoints; i++) {
            sx = position.x + cos(i*angle + rot) * radius;
            sy = position.y + sin(i*angle + rot) * radius; 
            vertices[i] = new PVector(sx, sy);
        }

        if (isKey) {
            stroke(255, 200*factor);
        } else {
            stroke(255, 200*factor);
            noFill();
        }
        strokeWeight(20);

        if (isKey) {
            if (containsPoint(vertices, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))) {
                fill(255, 255);
                stroke(255, 255);
                test+=0.02;
                radius = radius + cos(sin(frame*3)+frame*3)*test;
                isActive = true;
                endRadius+=0.5;
                if (endRadius >220) {
                    plop.lineWeight = 20;
                    plop.incrOut = 60;
                    plop.incrIn =60;
                    plop.alpha = 255;
                    plop.rot = random(180);
                    plop.position = new PVector(this.position.x, this.position.y);

                    radius = 0;
                    endRadius = rad;
                    npoints = int(random(3, 6));
                    update();
                    if (randomColor < colorPalette.length-1)
                        randomColor++;
                    else
                        randomColor=0;

                    var keyBall = polygons[int(random(polygons.length))];
                    keyBall.isKey = true;
                    isKey = false;

                    for (i = 0; i < polygons.length; i++) {
                        polygons[i].npoints = int(random(3, 6));
                        polygons[i].radius = 0;
                        polygons[i].update();
                    }
                }
            } else {
                noFill();
                isActive = false;
                if (endRadius >= 220 || endRadius != rad) {
                    endRadius-=0.5;
                }
                test = 0;
            }
        }

        pushMatrix();

        beginShape();
        for (let v of vertices) {
            vertex(v.x, v.y);
        }
        endShape(CLOSE);

        if (isKey) {
            strokeWeight(4);
            stroke(255, 255);
            line(position.x-4, position.y-4, position.x+5, position.y+4);
            line(position.x-4, position.y+4, position.x+5, position.y-4);
        }

        popMatrix();
    }

    function move() {
        position.x += map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 10*factor, -10*factor);
        position.y += map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 10*factor, -10*factor);

        if (position.x > width+radius) 
            position.x= 0-radius;
        if (position.x < 0-radius) 
            position.x= width+radius;
        if (position.y > height+radius) 
            position.y= 0-radius;
        if (position.y < 0-radius) 
            position.y= height+radius;
    }

    function update() {
        vertices = new Array(npoints);
        angle = TWO_PI / npoints;

        for (i = 0; i < npoints; i++) {
            sx = position.x + cos(i*angle) * radius;
            sy = position.y + sin(i*angle) * radius; 
            vertices[i] = new PVector(sx, sy);
        }
    }

    containsPoint(verts, px, py) {
        let num = verts.length;
        let i, j = num - 1;
        let oddNodes = false;
        for (i = 0; i < num; i++) {
            let vi = verts[i];
            let vj = verts[j];
            if (vi.y < py && vj.y >= py || vj.y < py && vi.y >= py) {
                if (vi.x + (py - vi.y) / (vj.y - vi.y) * (vj.x - vi.x) < px) {
                    oddNodes = !oddNodes;
                }
            }
            j = i;
        }
        return oddNodes;
    }
}

